-- The held card payment (P13-TSK-010, slice 2; PHASE_13_PLAN.md sections 7.3, 12.1, 12.3; C2; ADR-0108 decision 3's
-- HOLD row): CARD_PAYMENT admits HOLD - payments' authorise-and-defer, the card authorised and its capture held until a
-- person captures or voids it, or the hold validity lapses and payments voids it - beside the doors that honour it
-- (payments V034). Two CHECKs regenerated by name, both WIDENED, so every row already stored satisfies them:
--
--   risk_assessment_decision_admitted   RiskDecision.admittedBy: CARD_PAYMENT gains HOLD (WALLET_PAYMENT does not -
--                                       a wallet has no native hold at confirmation, C2)
--   risk_policy_knobs_coherent          a CARD_PAYMENT version MAY name a hold validity - exactly when one of its bands
--                                       or rules can decide HOLD, which RiskPolicy holds at the policy door (a version
--                                       written before HOLD was admitted names none, and stays valid); a WITHDRAWAL
--                                       version always names one, every other judged operation none
--
-- V002 and V007 are applied history for these two constraints; this file is their current definition, and the risk
-- migration tests follow them here. The numbering: V008 was the phase plan's reservation for P13-TSK-015's alerts
-- (wave D, not started when this landed); Flyway runs with out-of-order off, so a migration takes the next free number
-- in merge order and -015 takes the next free at its own build (PHASE_13_PLAN.md section 8's table, recorded).
-- The migration names no other schema.

ALTER TABLE risk.risk_assessment DROP CONSTRAINT risk_assessment_decision_admitted;

ALTER TABLE risk.risk_assessment
    -- RiskDecision.admittedBy: a decision the operation's consumer can honour (HOLD where a native hold exists: the
    -- withdrawal's hold-then-dispatch, and since P13-TSK-010 the card payment's authorise-and-defer).
    ADD CONSTRAINT risk_assessment_decision_admitted CHECK (
        (operation IN ('TRANSFER', 'CROSS_BORDER') AND decision IN ('ALLOW', 'CHALLENGE', 'DENY', 'REVIEW'))
        OR (operation = 'WITHDRAWAL' AND decision IN ('ALLOW', 'CHALLENGE', 'DENY', 'HOLD', 'REVIEW'))
        OR (operation = 'CARD_PAYMENT' AND decision IN ('ALLOW', 'CHALLENGE', 'DENY', 'HOLD'))
        OR (operation = 'WALLET_PAYMENT' AND decision IN ('ALLOW', 'CHALLENGE', 'DENY')));

ALTER TABLE risk.risk_policy DROP CONSTRAINT risk_policy_knobs_coherent;

ALTER TABLE risk.risk_policy
    -- Each operation's own knobs and no other's: a judged operation carries the challenge assurance and the override
    -- threshold (C7); the withdrawal always the hold validity, the card payment when its version can hold, no other
    -- operation ever; the sweep's policy carries none.
    ADD CONSTRAINT risk_policy_knobs_coherent CHECK (
        (operation = 'MONITORING'
            AND challenge_assurance IS NULL AND override_threshold_minor IS NULL AND hold_validity_hours IS NULL)
        OR (operation IN ('TRANSFER', 'WITHDRAWAL', 'CARD_PAYMENT', 'WALLET_PAYMENT', 'CROSS_BORDER')
            AND challenge_assurance IS NOT NULL AND override_threshold_minor IS NOT NULL
            AND (operation <> 'WITHDRAWAL' OR hold_validity_hours IS NOT NULL)
            AND (operation IN ('WITHDRAWAL', 'CARD_PAYMENT') OR hold_validity_hours IS NULL)));
